<script>
 import {onMount} from 'svelte';
 import {page} from '$app/stores';
 import {goto} from '$app/navigation';
 import {getProject,listProjectEnvironments,listEnvironmentSites,listSites,attachEnvironmentSite,detachEnvironmentSite,listDatabaseServers,listEnvironmentDatabases,attachEnvironmentDatabase,detachEnvironmentDatabase,listDatabases,listEnvironmentDatabaseInstances,attachEnvironmentDatabaseInstance,detachEnvironmentDatabaseInstance,updateProjectEnvironment,deleteProjectEnvironment,listProjectEnvironmentVariables,saveProjectEnvironmentVariable,deleteProjectEnvironmentVariable} from '$lib/api.js';
 import {notify} from '$lib/stores.js';
 import Button from '$lib/components/Button.svelte';
 let projectId='',environmentId='',environment=null,items=[],available=[],dbItems=[],dbAvailable=[],databaseInstances=[],dbInstanceAvailable=[],selected='',selectedDatabase='',selectedDatabaseInstance='',loading=true,busy=false,editName='',editDescription='',projectCanManage=false,environmentVariables=[],variableName='',variableValue='',variableBusy=false;
 async function load(){
  projectId=$page.params.id;environmentId=$page.params.environment_id;
  const projectResult=await getProject(projectId);projectCanManage=projectResult.ok&&!!projectResult.data?.project?.can_manage;
  const [e,s,all,db,envDb,allDatabases,envDbInstances]=await Promise.all([listProjectEnvironments(projectId),listEnvironmentSites(projectId,environmentId),listSites(projectId),listDatabaseServers(projectId),listEnvironmentDatabases(projectId,environmentId),listDatabases(projectId),listEnvironmentDatabaseInstances(projectId,environmentId),listProjectEnvironmentVariables(projectId,environmentId)]);
  if(!e.ok){notify(e.error||'Не удалось загрузить окружения','error');goto('/projects/'+projectId);return}
  environment=(e.data.environments||[]).find(x=>String(x.id)===String(environmentId))||null;
  if(environment){editName=environment.name;editDescription=environment.description||'';}
  if(!environment){notify('Окружение не найдено','error');goto('/projects/'+projectId);return}
  items=s.ok?s.data.sites||[]:[];
  const linked=new Set(items.map(x=>x.device_id+':'+x.site_id));
  available=all.ok?(all.data.sites||[]).filter(x=>!linked.has(x.device_id+':'+x.site.site_id)):[];
  dbItems=envDb.ok?envDb.data.database_servers||[]:[];
  const linkedDB=new Set(dbItems.map(x=>x.id));dbAvailable=db.ok?(db.data.servers||[]).filter(x=>!linkedDB.has(x.id)):[];
  databaseInstances=envDbInstances.ok?envDbInstances.data.databases||[]:[];
  environmentVariables=vars.ok?vars.data.variables||[]:[];
  const assignedDatabaseIds=new Set(databaseInstances.map(x=>x.id));
  const environmentServerIds=new Set(dbItems.map(x=>x.id));
  dbInstanceAvailable=allDatabases.ok?(allDatabases.data.databases||[]).filter(x=>environmentServerIds.has(x.server_id)&&!assignedDatabaseIds.has(x.id)):[];
  loading=false;
 }
 onMount(load);

 async function saveVariable(){if(variableBusy||!variableName.trim())return;variableBusy=true;const r=await saveProjectEnvironmentVariable(projectId,environmentId,variableName.trim(),variableValue);variableBusy=false;if(r.ok){notify(ru?'Переменная сохранена':'Variable saved','success');variableName='';variableValue='';await load()}else notify(r.error||'Не удалось сохранить переменную','error')}
 async function removeVariable(item){if(variableBusy||!confirm((ru?'Удалить переменную ':'Delete variable ')+item.name+'?'))return;variableBusy=true;const r=await deleteProjectEnvironmentVariable(projectId,environmentId,item.name);variableBusy=false;if(r.ok){notify(ru?'Переменная удалена':'Variable deleted','success');await load()}else notify(r.error||'Не удалось удалить переменную','error')}
 async function saveEnvironment(){if(busy||!environment)return;busy=true;const r=await updateProjectEnvironment(projectId,environmentId,editName,editDescription);busy=false;if(r.ok){notify('Окружение обновлено','success');await load()}else notify(r.error||'Не удалось обновить окружение','error')}
 async function removeEnvironment(){if(busy||!environment||environment.is_protected)return;if(!confirm('Удалить окружение? Привязки приложений к нему будут удалены, сами приложения останутся.'))return;busy=true;const r=await deleteProjectEnvironment(projectId,environmentId);busy=false;if(r.ok){notify('Окружение удалено','success');goto('/projects/'+projectId)}else notify(r.error||'Не удалось удалить окружение','error')}

 async function attach(){if(!selected||busy)return;const [device,site]=selected.split(':');busy=true;const r=await attachEnvironmentSite(projectId,environmentId,Number(device),site);busy=false;if(r.ok){notify('Application добавлено в окружение','success');selected='';await load()}else notify(r.error||'Не удалось добавить сайт','error')}
 async function attachDatabase(){if(!selectedDatabase||busy)return;busy=true;const r=await attachEnvironmentDatabase(projectId,environmentId,Number(selectedDatabase));busy=false;if(r.ok){notify('Database Server добавлен в окружение','success');selectedDatabase='';await load()}else notify(r.error||'Не удалось добавить Database Server','error')}
 async function detachDatabase(item){if(busy||environment?.is_protected)return;if(!confirm('Убрать Database Server из окружения? Сам сервер и базы останутся без изменений.'))return;busy=true;const r=await detachEnvironmentDatabase(projectId,environmentId,item.id);busy=false;if(r.ok){notify('Database Server убран из окружения','success');await load()}else notify(r.error||'Не удалось убрать Database Server','error')}
 async function attachDatabaseInstance(){if(!selectedDatabaseInstance||busy)return;busy=true;const r=await attachEnvironmentDatabaseInstance(projectId,environmentId,Number(selectedDatabaseInstance));busy=false;if(r.ok){notify('Database добавлена в окружение','success');selectedDatabaseInstance='';await load()}else notify(r.error||'Не удалось добавить базу в окружение','error')}
 async function detachDatabaseInstance(item){if(busy||environment?.is_protected)return;if(!confirm('Убрать базу из окружения? Сама база и её данные останутся.'))return;busy=true;const r=await detachEnvironmentDatabaseInstance(projectId,environmentId,item.id);busy=false;if(r.ok){notify('База убрана из окружения','success');await load()}else notify(r.error||'Не удалось убрать базу','error')}
 async function detach(item){if(busy||environment?.is_protected)return;if(!confirm('Убрать приложение из окружения? Сам сайт и его файлы останутся.'))return;busy=true;const r=await detachEnvironmentSite(projectId,environmentId,item.device_id,item.site_id);busy=false;if(r.ok){notify('Приложение удалено из окружения','success');await load()}else notify(r.error||'Не удалось удалить привязку','error')}
</script>
{#if loading}<div class="empty">Загрузка окружения…</div>{:else if environment}
<div class="page-header"><div><button class="back" on:click={()=>goto('/projects/'+projectId)}>← Project</button><div class="eyebrow">PROJECT / ENVIRONMENT</div><h1 class="page-title">{environment.name}</h1><p class="page-desc">{environment.description||environment.slug} · {environment.is_protected?'Protected environment':'Environment'}</p></div></div>
{#if projectCanManage}<section class="panel settings-panel"><div class="section-head"><div><h2>Environment settings</h2><p>{environment.is_protected?'Production is protected; only its description can be changed.':'Изменение имени и описания окружения.'}</p></div></div><div class="settings-fields"><label>Название<input class="input" bind:value={editName} disabled={environment.is_protected}/></label><label>Описание<input class="input" bind:value={editDescription}/></label><div class="settings-actions"><Button variant="primary" disabled={busy} on:click={saveEnvironment}>Сохранить</Button>{#if !environment.is_protected}<Button variant="danger" disabled={busy} on:click={removeEnvironment}>Удалить окружение</Button>{/if}</div></div></section>{/if}
<section class="panel env-vars-panel"><div class="section-head"><div><h2>{ru?'Переменные окружения и секреты':'Environment variables & secrets'}</h2><p>{ru?'Отдельные значения для этого окружения. Значения шифруются и никогда не показываются повторно.':'Values belong only to this environment. Secrets are encrypted at rest and never shown again.'}</p></div><span>{environmentVariables.length}</span></div>
{#if projectCanManage}<div class="env-var-form"><label>{ru?'Ключ':'Key'}<input class="input" bind:value={variableName} maxlength="64" placeholder="API_KEY" autocomplete="off"/></label><label>{ru?'Значение':'Value'}<input class="input" type="password" bind:value={variableValue} maxlength="16384" placeholder={ru?'Новое значение секрета':'New secret value'} autocomplete="new-password"/></label><Button variant="primary" disabled={variableBusy||!variableName.trim()} loading={variableBusy} on:click={saveVariable}>{ru?'Сохранить':'Save variable'}</Button></div><small class="env-var-hint">{ru?'Сохранение существующего ключа заменит его значение. Допускаются A–Z, 0–9 и подчёркивание; системные ключи зарезервированы.':'Saving an existing key replaces its value. A–Z, 0–9 and underscore are accepted; system keys are reserved.'}</small>{/if}
{#if environmentVariables.length}<div class="resource-list env-var-list">{#each environmentVariables as item}<div class="resource-row"><div class="resource"><span class="resource-icon">ENV</span><span><strong>{item.name}</strong><small>•••••••••••• · {ru?'Значение зашифровано':'Encrypted value'}</small></span></div>{#if projectCanManage}<Button variant="danger" disabled={variableBusy} on:click={()=>removeVariable(item)}>{ru?'Удалить':'Delete'}</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">{ru?'Переменные для этого окружения ещё не заданы.':'No variables configured for this environment yet.'}</div>{/if}</section>
<section class="panel"><div class="section-head"><div><h2>Applications</h2><p>Сайты, назначенные в это окружение</p></div>{#if projectCanManage}<div class="add"><select class="input" bind:value={selected}><option value="">Выбрать приложение проекта</option>{#each available as item}<option value={item.device_id+':'+item.site.site_id}>{item.site.site_id} · {item.device_name}</option>{/each}</select><Button variant="primary" disabled={!selected||busy} on:click={attach}>Добавить</Button></div>{/if}</div>
{#if items.length}<div class="resource-list">{#each items as item}<div class="resource-row"><a class="resource" href={'/sites/'+item.device_id+'/'+encodeURIComponent(item.site_id)+'?project_id='+projectId+'&environment_id='+environmentId}><span class="resource-icon">◉</span><span><strong>{item.site_id}</strong><small>{item.device_name}</small></span><span class="open">Открыть →</span></a>{#if projectCanManage && !environment.is_protected}<Button variant="danger" disabled={busy} on:click={()=>detach(item)}>Убрать</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">В этом окружении пока нет приложений.</div>{/if}</section>
<section class="panel database-panel"><div class="section-head"><div><h2>Database Servers</h2><p>Серверы баз данных, назначенные в это окружение</p></div>{#if projectCanManage}<div class="add"><select class="input" bind:value={selectedDatabase}><option value="">Выбрать Database Server</option>{#each dbAvailable as db}<option value={db.id}>{db.name} · {db.engine}</option>{/each}</select><Button variant="primary" disabled={!selectedDatabase||busy} on:click={attachDatabase}>Добавить</Button></div>{/if}</div>
{#if dbItems.length}<div class="resource-list">{#each dbItems as db}<div class="resource-row"><a class="resource" href={'/databases?project_id='+projectId+'&environment_id='+environmentId}><span class="resource-icon">DB</span><span><strong>{db.name}</strong><small>{db.engine} · Device #{db.device_id} · {db.status}</small></span><span class="open">Открыть →</span></a>{#if projectCanManage && !environment.is_protected}<Button variant="danger" disabled={busy} on:click={()=>detachDatabase(db)}>Убрать</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">В окружение пока не добавлены Database Servers.</div>{/if}
</section>
<section class="panel database-panel"><div class="section-head"><div><h2>Databases</h2><p>Отдельные базы данных, назначенные в это окружение</p></div>{#if projectCanManage}<div class="add"><select class="input" bind:value={selectedDatabaseInstance}><option value="">Выбрать базу проекта</option>{#each dbInstanceAvailable as item}<option value={item.id}>{item.name} · {item.server_name}</option>{/each}</select><Button variant="primary" disabled={!selectedDatabaseInstance||busy} on:click={attachDatabaseInstance}>Добавить</Button></div>{/if}</div>
{#if databaseInstances.length}<div class="resource-list">{#each databaseInstances as item}<div class="resource-row"><a class="resource" href={'/databases/'+item.id+'?project_id='+projectId+'&environment_id='+environmentId}><span class="resource-icon">DB</span><span><strong>{item.name}</strong><small>{item.server_name} · {item.engine} · Device #{item.device_id} · {item.status}</small></span><span class="open">Открыть →</span></a>{#if projectCanManage && !environment.is_protected}<Button variant="danger" disabled={busy} on:click={()=>detachDatabaseInstance(item)}>Убрать</Button>{/if}</div>{/each}</div>{:else}<div class="empty compact">В окружение пока не добавлены отдельные базы данных.</div>{/if}</section>

{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.12em;color:#a1a1aa;margin:7px 0}.back{border:0;background:none;color:#a1a1aa;font-size:11px;margin-bottom:8px}.settings-panel{margin-bottom:14px}.database-panel{margin-top:14px}.env-var-form{display:grid;grid-template-columns:1fr 2fr auto;align-items:end;gap:9px}.env-var-form label{display:grid;gap:6px;font-size:10px;color:#a1a1aa}.env-var-hint{display:block;color:#a1a1aa;font-size:10px;margin:9px 0 14px}.env-var-list{margin-top:12px}.settings-fields{display:grid;grid-template-columns:1fr 2fr;gap:10px}.settings-fields label{display:grid;gap:6px;font-size:10px;color:#a1a1aa}.settings-actions{grid-column:1/-1;display:flex;gap:8px}.panel{background:#18181b;border:1px solid #27272a;border-radius:9px;padding:16px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.section-head h2{font-size:13px}.section-head p,.resource small{font-size:10px;color:#a1a1aa;margin-top:4px}.add{display:flex;gap:7px}.add select{min-width:220px}.resource-list{display:grid;gap:7px}.resource-row{display:flex;align-items:center;gap:8px}.resource-row .resource{flex:1}.resource{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid #27272a;border-radius:7px;text-decoration:none;color:inherit}.resource-icon{width:29px;height:29px;display:grid;place-items:center;background:#27272a;border-radius:6px}.resource>span:nth-child(2){display:grid;flex:1}.resource strong{font-size:11px}.open{font-size:10px;color:#a1a1aa}.empty.compact{padding:20px;color:#a1a1aa;font-size:11px}@media(max-width:650px){.section-head{align-items:stretch;flex-direction:column}.add select{min-width:0;flex:1}.env-var-form,.settings-fields{grid-template-columns:1fr}.settings-actions{grid-column:auto}}
</style>
